svg.script:
var chip = {

  menu: {
    'Value +1': {
      eventName: 'value_incr_1',
      otherEvents: ['dblclick'],
      applicable: (node) => { return true },
      handler: function(evt) {
        chip.increment(this, 1)
      },
    },
    'Value -1': {
      eventName: 'value_decr_1',
      otherEvents: ['dblclick'],
      applicable: (node) => { return true },
      handler: function(evt) {
        chip.increment(this, -1)
      },
    },
  },

  increment: function(elem, step) {
    const tspan = elem.querySelector('tspan')
    const current = parseInt(tspan.textContent)
    tspan.textContent = String(current + step)
  },

  label_on: function(elem) {
    svgElem = elem.querySelector(':scope > svg')
    svgElem.setAttribute('viewBox', '0 0 80 110')
    svgElem.setAttribute('height', '110')
  },

  label_off: function(elem) {
    svgElem = elem.querySelector(':scope > svg')
    svgElem.setAttribute('viewBox', '0 0 80 80')
    svgElem.setAttribute('height', '80')
    if (svgElem.getAttribute('height') == '80') {
      return
    } else {
      svgElem.setAttribute('y', parseFloat(svgElem.getAttribute('y')) + 15)
    }
  },

  positions_change_handler: function(elem, departedElements, arrivingElements) {
    return
    // TODO...
    tVal = elem.querySelector('.tspan_value')
    tSum = elem.querySelector('.tspan_sum')
    let aboveSum = 0
    if (arrivingElements.size) {
        chip.label_on(elem)
        for (const [xy, occupant] of arrivingElements) {
          chip.label_off(occupant)
          aboveTspan = occupant.querySelector('.tspan_sum')
          aboveSum += parseInt(aboveTspan.textContent)
        }
    } else {
        chip.label_off(elem)
    }
    tSum.textContent = parseInt(tVal.textContent) + aboveSum
  },

}
